/** Режим отображения виджета. */
export type ChartWidgetMode = 'sales' | 'monitoring';

/** Точка временного ряда: [timestamp в мс, значение]. `null` — пропуск (нет данных). */
export type TimePoint = [timestamp: number, value: number | null];

export interface TimeSeries {
    id: string;
    name: string;
    points: TimePoint[];
}

/**
 * Единый формат данных для обоих режимов: виджет сам решает,
 * каким движком и с какими настройками их нарисовать.
 */
export interface ChartWidgetDataset {
    title: string;
    series: TimeSeries[];
    /** Единица измерения значений, например `₽` или `ms`. */
    unit?: string;
    /** Знаков после запятой в подписях и тултипе. */
    precision?: number;
}

export type ChartWidgetDatasets = Record<ChartWidgetMode, ChartWidgetDataset>;
EOF
cat > colors.ts <<'EOF'
// Категориальная палитра: цвет закреплён за позицией ряда, а не за его рангом.
// Тёмная тема — отдельно подобранные ступени тех же оттенков.
const CATEGORICAL = {
    light: ['#2a78d6', '#eb6834', '#1baf7a', '#eda100', '#e87ba4', '#008300', '#6250d6', '#e34948'],
    dark: ['#3987e5', '#d95926', '#199e70', '#c98500', '#d55181', '#008300', '#9085e9', '#e66767'],
};

export type ColorScheme = keyof typeof CATEGORICAL;

export function getSeriesColors(scheme: ColorScheme): string[] {
    return CATEGORICAL[scheme];
}
EOF
cat > chartkit-setup.ts <<'EOF'
import {settings} from '@gravity-ui/chartkit';
import {GravityChartsPlugin} from '@gravity-ui/chartkit/gravity-charts';
import {YagrPlugin} from '@gravity-ui/chartkit/yagr';

// Плагины регистрируются один раз. Сам код движков сюда не попадает:
// renderer каждого плагина — React.lazy, и его чанк скачивается
// только при первом рендере <ChartKit type="..."/> этого типа.
settings.set({plugins: [GravityChartsPlugin, YagrPlugin], lang: 'ru'});
EOF
cat > adapters.ts <<'EOF'
import type {ChartKitType, ChartKitWidget} from '@gravity-ui/chartkit';

import {type ColorScheme, getSeriesColors} from './colors';
import type {ChartWidgetDataset, ChartWidgetMode} from './types';

export type ChartKitConfig = {
    [T in ChartKitType]: {type: T; data: ChartKitWidget[T]['data']};
}[ChartKitType];

interface AdapterOptions {
    colorScheme: ColorScheme;
}

function withUnit(unit?: string) {
    return unit ? ` ${unit}` : '';
}

/** Обычный линейный график (gravity-charts): немного точек, маркеры, подробный тултип. */
export function toGravityChartsConfig(
    dataset: ChartWidgetDataset,
    {colorScheme}: AdapterOptions,
): ChartKitConfig {
    const colors = getSeriesColors(colorScheme);
    const precision = dataset.precision ?? 0;

    return {
        type: 'gravity-charts',
        data: {
            title: {text: dataset.title},
            colors,
            legend: {enabled: dataset.series.length > 1},
            xAxis: {type: 'datetime', labels: {dateFormat: 'MMM YYYY'}},
            yAxis: [
                {
                    labels: {numberFormat: {precision: 0, unit: 'auto'}},
                    title: dataset.unit ? {text: dataset.unit} : undefined,
                },
            ],
            tooltip: {
                valueFormat: {type: 'number', precision, postfix: withUnit(dataset.unit)},
            },
            series: {
                data: dataset.series.map((serie, index) => ({
                    type: 'line',
                    id: serie.id,
                    name: serie.name,
                    color: colors[index],
                    lineWidth: 2,
                    marker: {states: {normal: {enabled: true, radius: 4}}},
                    data: serie.points.map(([x, y]) => ({x, y})),
                })),
            },
        },
    };
}

/** Плотный временной ряд (yagr/uPlot): тысячи точек, общий timeline, zoom выделением. */
export function toYagrConfig(dataset: ChartWidgetDataset, {colorScheme}: AdapterOptions): ChartKitConfig {
    const colors = getSeriesColors(colorScheme);
    const precision = dataset.precision ?? 0;

    // yagr требует общий timeline и выровненные по нему массивы значений.
    const timeline = Array.from(
        new Set(dataset.series.flatMap((serie) => serie.points.map(([ts]) => ts))),
    ).sort((a, b) => a - b);
    const indexByTs = new Map(timeline.map((ts, index) => [ts, index]));

    const graphs = dataset.series.map((serie, index) => {
        const data: (number | null)[] = new Array(timeline.length).fill(null);
        for (const [ts, value] of serie.points) {
            data[indexByTs.get(ts)!] = value;
        }
        return {id: serie.id, name: serie.name, color: colors[index], data};
    });

    return {
        type: 'yagr',
        data: {
            data: {timeline, graphs},
            libraryConfig: {
                title: {text: dataset.title},
                chart: {
                    series: {type: 'line', width: 1.5, spanGaps: false},
                    select: {zoom: true},
                },
                axes: {
                    y: {
                        precision,
                        values: (_, ticks) => ticks.map((tick) => `${tick}${withUnit(dataset.unit)}`),
